<?php $row=$goal ?? []; $editing=isset($goal); ?><form class="stack" action="/growth<?= $editing ? '/'.e($goal['id']).'/edit' : '' ?>" method="post"><?= csrf_field() ?><label>Goal title<input name="title" value="<?= e($row['title'] ?? '') ?>" maxlength="200" required></label><label>Area<select name="category"><?php foreach (GrowthService::CATEGORIES as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($row['category'] ?? 'personal')===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Time horizon<select name="horizon"><option value="short" <?= ($row['horizon'] ?? 'short')==='short' ? 'selected' : '' ?>>Short term</option><option value="long" <?= ($row['horizon'] ?? '')==='long' ? 'selected' : '' ?>>Long term</option></select></label><label>Target date (optional)<input type="date" name="due_date" value="<?= e($row['due_date'] ?? '') ?>"></label><label>Prerequisite goal<select name="depends_on"><option value="">No prerequisite</option><?php foreach ($goals as $option) if (!$editing || $option['id']!==$goal['id']): ?><option value="<?= e($option['id']) ?>" <?= ($row['depends_on'] ?? null)===$option['id'] ? 'selected' : '' ?>><?= e($option['title']) ?> · <?= e($option['status']) ?></option><?php endif; ?></select></label><label>Notes / skill you want to develop<textarea name="notes" maxlength="5000" rows="3"><?= e($row['notes'] ?? '') ?></textarea></label><label>Status<select name="status"><?php foreach (['active'=>'Active','paused'=>'Paused','done'=>'Done'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($row['status'] ?? 'active')===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button><?= $editing ? 'Save goal' : 'Create goal' ?></button></form>
